    @Test
    fun `the purr sample's blocks guard and release the way its comments claim`() {
        // The sample's expected output is its own comments, one per `println`. What makes this worth
        // running rather than just compiling is that a lock leak does not show up as a wrong answer
        // until something tries to take the same lock again — which the sample does, several times
        // over, so a missing unlock deadlocks here instead of passing quietly.
        val directory = Files.createTempDirectory("neko-purr-sample")
        val result = compileSample(purrSamplePath(), outputDirectory = directory)
        assertTrue(
            !result.hasErrors,
            "the purr sample must compile:\n${result.renderDiagnostics().joinToString("\n")}",
        )

        val loader = java.net.URLClassLoader(arrayOf(directory.toUri().toURL()), javaClass.classLoader)
        val type = Class.forName("com.github.kusa233.neko.sample.PurrSample", true, loader)
        val main = type.getMethod("main", Array<String>::class.java)

        val original = System.out
        val buffer = java.io.ByteArrayOutputStream()
        System.setOut(java.io.PrintStream(buffer, true, Charsets.UTF_8))
        try {
            // Joined with a timeout: the failure mode of a forgotten unlock is a deadlock, and a test
            // that hangs says less than one that fails.
            val thread = Thread { main.invoke(null, arrayOf<String>()) }
            thread.isDaemon = true
            thread.start()
            thread.join(30_000)
            assertTrue(!thread.isAlive, "the purr sample deadlocked: a lock was never released")
        } finally {
            System.setOut(original)
        }

        assertEquals(
            listOf(
                "5",
                "42",
                "2",
                "2",
                "1",
            ),
            buffer.toString(Charsets.UTF_8).replace("\r\n", "\n").trim().lines(),
            "the sample should print the totals its comments claim",
        )
    }

    @Test
    fun `the for sample runs and prints the values its comments claim`() {
        // The comments in `ForSample.neko` each name the value the `println` above them should print,
        // so this checks the language against its own documentation. Running it is what makes that a
        // real check: a loop that iterates once too often, or an `iinc` on the wrong type, still
        // compiles and only shows up as a wrong number here.
        val directory = Files.createTempDirectory("neko-for-sample")
        val result = compileSample(forSamplePath(), outputDirectory = directory)
        assertTrue(
            !result.hasErrors,
            "the for sample must compile:\n${result.renderDiagnostics().joinToString("\n")}",
        )

        val loader = java.net.URLClassLoader(arrayOf(directory.toUri().toURL()), javaClass.classLoader)
        val type = Class.forName("com.github.kusa233.neko.sample.ForSample", true, loader)
        val main = type.getMethod("main", Array<String>::class.java)

        val original = System.out
        val buffer = java.io.ByteArrayOutputStream()
        System.setOut(java.io.PrintStream(buffer, true, Charsets.UTF_8))
        try {
            // The array loop prints this program's own `main` arguments, so passing none is what makes
            // that section print nothing — which is itself the assertion that an empty array iterates
            // zero times rather than once with a null element.
            main.invoke(null, arrayOf<String>())
        } finally {
            System.setOut(original)
        }

        assertEquals(
            listOf(
                "15",   // 1 + 2 + 3 + 4 + 5
                "3", "2", "1", // counting down
                "4",    // 1, 3, 9, 27
                "6",    // 0 + 2 + 4
                "6",    // 2 * 3 rows and columns
                "miao", "nya", "purr", // the Iterable
                "3",    // how many words it yielded
                "11", "9", "2", "101", // ++ and -- on int, byte and long
                "64",   // 8 * 8 is the first square over 50
            ),
            buffer.toString(Charsets.UTF_8).replace("\r\n", "\n").trim().lines(),
            "the sample should print the values its comments claim",
        )
    }

    @Test
    fun `the exception sample's handler answers the value its scratch site takes`() {
        val result = compileSample(exceptionSamplePath())
        val bytes = result.classes.getValue("com/github/kusa233/neko/sample/ExceptionSample")

        val methods = mutableMapOf<String, String>()
        org.objectweb.asm.ClassReader(bytes).accept(
            object : org.objectweb.asm.ClassVisitor(org.objectweb.asm.Opcodes.ASM9) {
                override fun visitMethod(
                    access: Int,
                    name: String,
                    descriptor: String,
                    signature: String?,
                    thrown: Array<out String>?,
                ): org.objectweb.asm.MethodVisitor? {
                    methods[name] = descriptor
                    return null
                }
            },
            org.objectweb.asm.ClassReader.SKIP_CODE,
        )

        // There is no extractor class any more: the `{ ... }` block became a method of the sample's own
        // class, so this asserts on that method instead of on a generated interface's `invoke`. The
        // handler `nyan`s 1, and the `scratch` that reaches it declares an `int`, so the method answers
        // an `int` — the value the `try` is worth when the call returns through it.
        assertEquals(
            "(III)I",
            methods["main\$scratch\$0"],
            "the handler takes its emit values and answers what the scratch site declared",
        )
    }

    /**
     * Analyses [content] as a program that includes the standard library, and returns the errors.
     *
     * Parsing and analysis are driven directly rather than through [Compiler] because these tests
     * assert on diagnostics that code generation never reaches — an unreachable statement, a
     * redeclared variable. The library is still part of the program, because a `raise` without it is
     * rejected before the rule under test is ever considered.
     */
    private fun analyzeWithLibrary(name: String, content: String): List<com.github.kusa233.neko.diagnostics.Diagnostic> {
        val diagnostics = com.github.kusa233.neko.diagnostics.DiagnosticBag()
        val files = TestSupport.standardLibrarySources().map {
            com.github.kusa233.neko.parser.Parser(it, diagnostics).parseFile()
        } + com.github.kusa233.neko.parser.Parser(SourceFile(name, content), diagnostics).parseFile()
        check(!diagnostics.hasErrors) {
            "the library and the sample must parse, but got:\n" +
                diagnostics.diagnostics.joinToString("\n") { it.toString() }
        }

        val program = com.github.kusa233.neko.ast.NekoProgram(files)
        com.github.kusa233.neko.analyzer.Analyzer(program, diagnostics).analyze()
        return diagnostics.diagnostics.filter { it.severity == Severity.ERROR }
    }

    /**
     * The statement after a departing `yield` must be reported at error level.
     *
     * The sample used to carry an `raise` with an unreachable line beneath it; with `scratch` there is
     * no such thing, because `scratch` *returns*. The unreachable case now belongs to `yield`, so the
     * test builds that program rather than reading it out of the sample — the rule is the same one.
     */
    @Test
    fun `the statement after a yield is an error at the line it sits on`() {
        val content = TestSupport.file(
            "class Emitter {",
            "    static {",
            "        fun value(): int {",
            "            yield 1",
            "            println(\"unreachable\")",
            "            return 2",
            "        } emit [int]",
            "    }",
            "}",
        )
        val error = analyzeWithLibrary("Emit.neko", content).single()
        assertEquals(
            "unreachable statement: execution cannot continue past the preceding 'yield'",
            error.message,
        )
        assertEquals(
            TestSupport.locationOf(content, "println(\"unreachable\")"),
            "${error.span?.line}:${error.span?.column}",
            "the error belongs on the unreachable line",
        )
    }

    @Test
    fun `the sample's emit clause reaches the class file`() {
        val result = compileSample(exceptionSamplePath())
        val bytes = result.classes.getValue("com/github/kusa233/neko/sample/ExceptionSample")
        // Read the class back with ASM rather than by running it: the point here is the metadata.
        //
        // The sample never writes a `throws` clause — that keyword is gone from the language. It
        // writes `} emit [int, int]`, which is the same promise in the language's own spelling: the
        // function may leave by throwing rather than by returning. The class file records
        // `EmitYieldException`, which is what that departure actually is now.
        val reader = org.objectweb.asm.ClassReader(bytes)
        val exceptions = mutableListOf<String>()
        reader.accept(
            object : org.objectweb.asm.ClassVisitor(org.objectweb.asm.Opcodes.ASM9) {
                override fun visitMethod(
                    access: Int,
                    name: String,
                    descriptor: String,
                    signature: String?,
                    thrown: Array<out String>?,
                ): org.objectweb.asm.MethodVisitor? {
                    if (name == "emitTest") exceptions += thrown.orEmpty()
                    return null
                }
            },
            org.objectweb.asm.ClassReader.SKIP_CODE,
        )
        assertEquals(
            listOf("com/github/kusa233/neko/stdlib/emit/EmitYieldException"),
            exceptions,
            "an 'emit' clause belongs in the class file's Exceptions attribute",
        )
    }

    @Test
    fun `the output directory the compiler is given is inside the project`() {
        // The build hands the compiler `neko-compile/classes`, resolved against the project
        // directory. Asserting the shape here catches a change to that convention — a path that
        // escapes the project (a drive-relative one, say) writes the class files somewhere the
        // `runNekoSample` task would not find them.
        val relative = Path.of(TestSupport.OUTPUT_DIRECTORY)
        assertFalse(relative.isAbsolute, "the output path must be relative, not absolute")
        assertEquals("neko-compile", relative.first().toString())
        assertEquals("classes", relative.last().toString())

        val resolved = TestSupport.projectDirectory.resolve(relative).normalize()
        assertTrue(
            resolved.startsWith(TestSupport.projectDirectory),
            "the output directory must stay inside the project, but was $resolved",
        )
        assertEquals("classes", resolved.fileName.toString())
    }

    @Test
    fun `the sample's commented-out line is a genuine error`() {
        // Sample lines 14-15 are `// Error to compile:` / `// str: string = "new value"`. Uncommenting
        // that line must fail, at that line, pointing at the redeclared name — this is the rule the
        // sample's comments exist to state.
        val original = Files.readString(samplePath())
        val uncommented = original.replace(
            "// str: string = \"new value\"",
            "str: string = \"new value\"",
        )
        assertTrue(uncommented != original, "the sample should still contain the commented-out line")

        val error = analyzeWithLibrary("Sample.neko", uncommented).single()
        assertEquals(
            "variable 'str' is already declared in this scope",
            error.message,
        )
        // The positions are derived from the sample rather than written out, so moving the comment
        // — as editing the sample does — cannot leave a stale line number behind.
        assertEquals(
            TestSupport.locationOf(uncommented, "str: string = \"new value\""),
            "${error.span?.line}:${error.span?.column}",
            "the error belongs on the sample's commented-out line",
        )
        assertEquals(
            TestSupport.locationOf(uncommented, "str: string = \"Hell"),
            "${error.notes.single().span?.line}:${error.notes.single().span?.column}",
            "the note should point at the sample's first declaration of 'str'",
        )
    }
}
